# Background value stays the same except for cells that are between special values.
# Special values stay the same.
# Cells between two special values (horizontally or vertically) become 3.

def transform(grid):
    H, W = len(grid), len(grid[0])
    background = grid[0][0]  # Background value (should be the same everywhere except special cells)
    special = None
    special_positions = set()

    # Identify background and special values
    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            if val != background:
                if special is None:
                    special = val
                elif special != val:
                    raise ValueError(f"Inconsistent special values in grid")

    if special is None:
        # No special values, just return background
        return grid

    special_positions = set((r, c) for r in range(H) for c in range(W) if grid[r][c] == special)

    output = [[background] * W for _ in range(H)]

    # For each row, fill between adjacent special values horizontally
    for r in range(H):
        row_special = sorted([c for c in range(W) if (r, c) in special_positions])
        if len(row_special) > 1:
            for i in range(len(row_special) - 1):
                for c in range(row_special[i] + 1, row_special[i+1]):
                    output[r][c] = 3

    # For each column, fill between adjacent special values vertically
    for c in range(W):
        col_special = sorted([r for r in range(H) if (r, c) in special_positions])
        if len(col_special) > 1:
            for i in range(len(col_special) - 1):
                for r in range(col_special[i] + 1, col_special[i+1]):
                    output[r][c] = 3

    # Special values stay as special
    for r in range(H):
        for c in range(W):
            if (r, c) in special_positions:
                output[r][c] = special

    return output

